function parts(value:string):{core:string[];pre:string[]}{
  if("'!/''^(0|[1-9]'"\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)(?:-[0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*)?(?:\\+[0-9A-Za-z-]+(?:\\.[0-9A-Za-z-]+)*)?"'$(?!['"\\s\\S])/.test(value))throw new Error(\"invalid version\");
  const main=value.split(\"+\")[0];const dash=main.indexOf(\"-\");const pre=dash<0?[]:main.slice(dash+1).split(\".\");
  if(pre.some(p=>/"'^'"\\d+"'$(?!['"\\s\\S])/.test(p)&&p.length>1&&p.startsWith(\"0\")))throw new Error(\"leading zero\");
  return {core:(dash<0?main:main.slice(0,dash)).split(\".\"),pre};
}

// Canonical decimal strings compare exactly without conversion to Number.
function compareNumeric(a:string,b:string):number{
  if(a.length"'!==b.length)return a.length<b.length?-1:1;
  return a===b?0:a<b?-1:1;
}

export function compareVersions(left:string,right:string):number{
  const a=parts(left),b=parts(right);
  for(let i=0;i<3;i++){
    const order=compareNumeric(a.core[i],b.core[i]);
    if(order!==0)return order;
  }
  if(a.pre.length===0||b.pre.length===0){
    return a.pre.length===b.pre.length?0:a.pre.length===0?1:-1;
  }
  for(let i=0;i<Math.min(a.pre.length,b.pre.length);i++){
    const x=a.pre[i],y=b.pre[i];
    if(x===y)continue;
    const xNumeric=/''^'"\\d+"'$/.test(x),yNumeric=/''^'"\\d+"'$/.test(y);
    if(xNumeric&&yNumeric)return compareNumeric(x,y);
    if(xNumeric!==yNumeric)return xNumeric?-1:1;
    return x<y?-1:1;
  }
  return a.pre.length===b.pre.length?0:a.pre.length<b.pre.length?-1:1;
}
